/* Pure rules for Eldoria's city-life expansion; no renderer or browser storage. */
(()=>{'use strict';
const quiz=(title,prompt,choices,answer,hint)=>({kind:'choice',title,prompt,choices,answer,hint});
const order=(title,prompt,choices,answer,hint)=>({kind:'sequence',title,prompt,choices,answer,hint});
const P={
 leather:quiz('Weatherproof courier boots','The route is wet, muddy and long. Which material fits the order?',['Silk uppers','Waxed leather','Untreated paper'],1,'Look for a material that resists wet conditions.'),
 stitch:order('Finish the courier order','Follow the job card: cut the pattern, stitch the panels, then seal the seams.',['Seal seams','Cut pattern','Stitch panels'],[1,2,0],'The pieces need their shape before joining.'),
 repair:quiz('A loose lantern bracket','The lantern is sound, but its wall bracket wobbles. What should you fix first?',['Paint the lantern','Secure the bracket with sound fittings','Hang a heavier lantern'],1,'Repair the part that supports the weight.'),
 bread:order('Morning woodland loaves','The recipe card reads: mix, knead, prove, bake. Put the work in order.',['Bake','Prove','Mix','Knead'],[2,3,1,0],'Give the dough time to rise before using the oven.'),
 portions:quiz('Enough for the supper table','One tray serves four guests. Fern has twelve guests tonight. How many trays are needed?',['Two trays','Three trays','Six trays'],1,'Divide twelve guests by four servings.'),
 tea:order('A calm tea service','Follow Fern’s service card: warm the pot, add the leaves, pour water, then let it steep.',['Pour water','Let it steep','Warm the pot','Add leaves'],[2,3,0,1],'The pot is warmed before the tea is prepared.'),
 medicine:quiz('The healing recipe','Professor Thistle’s card calls for moonleaf, springwater and honey. Which tray matches it?',['Moonleaf, springwater, honey','Moonleaf, dragon ash, honey','Nightshade, springwater, honey'],0,'Use exactly the ingredients on the card.'),
 labels:quiz('A careful bottle label','Two similar bottles stand on the bench. What makes a safe label?',['Only a pretty symbol','The name, ingredients and preparation date','Only the color of the liquid'],1,'A label must tell someone what is inside.'),
 herbs:order('Prepare the moonleaf harvest','The keeper’s method is inspect, gather, rinse, then label.',['Rinse','Label','Inspect','Gather'],[2,3,0,1],'Check the plants before taking anything.'),
 soil:quiz('The drooping greenhouse plant','The soil is waterlogged and the pot has no drainage. What is the best first change?',['Add much more water','Improve drainage and reduce watering','Cover every leaf with cloth'],1,'Waterlogged roots need air as well as moisture.'),
 garden:order('A new moonflower bed','Prepare the soil, sow seeds, water gently, then mark the row.',['Mark row','Sow seeds','Prepare soil','Water gently'],[2,1,3,0],'Start with the place where the roots will grow.'),
 bouquet:quiz('A considerate harvest','The sanctuary needs flowers and pollinators need food. What is the best plan?',['Cut every flower','Take a small share and leave plenty blooming','Pull the roots out'],1,'Leave the garden able to keep growing.'),
 catalog:order('Put the family files in order','The labels must be alphabetized: Briarvale, Glassmere, Redfern, Silverstitch.',['Silverstitch','Briarvale','Redfern','Glassmere'],[1,3,2,0],'Compare the first letter of each family name.'),
 letter:quiz('A misdirected parcel','The label reads “Family Portrait Gallery, Library District.” Where should it go?',['Moonleaf Tavern','Family Library','Lantern Festival'],1,'The destination is written on the label.'),
 record:quiz('A damaged document','A brittle page is tearing. What should you do?',['Force the book flat','Support it gently and ask the archivist for preservation help','Scrub the ink'],1,'Protect the original rather than risking more damage.'),
 route:order('The morning delivery round','The manifest specifies Capital → Market → Cottage. Follow its route.',['Cottage','Capital','Market'],[1,2,0],'Start where the manifest begins.'),
 parcel:quiz('Deliver to the right person','A sealed parcel is marked “Master Cobble, Silverstitch Workshop.” Who should receive it?',['Master Cobble','Queen Aveline','Keeper Willow'],0,'Read both the recipient and the destination.'),
 bridge:quiz('A safe river crossing','The water is rising. Which route should the courier choose?',['The marked, open bridge','An unmarked slippery riverbank','The deepest part of the stream'],0,'Use the maintained public crossing.'),
 melody:order('The lantern-keeper’s refrain','Aurelia plays Moon, Star, Leaf, Star. Repeat the melody.',['Leaf','Moon','Star'],[1,2,0,2],'The Star note appears twice.'),
 stars:order('The observatory pattern','Remember the chart: Lantern, Leaf, Moon, Lantern.',['Moon','Lantern','Leaf'],[1,2,0,1],'The first symbol is also the last.'),
 kindness:quiz('The frightened moonfox','A young moonfox hides under a fern. How should you help?',['Chase it into the crowd','Give it space, fresh water and a quiet path away','Wake it repeatedly'],1,'Safety and choice matter more than forcing a meeting.'),
 charter:quiz('A fair travel charter','Families need safe travel. Which policy protects poor travelers too?',['Charge every child a large fee','Provide a free register and staffed meeting points','Close all gates forever'],1,'A useful protection should not exclude families who cannot pay.'),
 budget:quiz('The community repair fund','There are 60 mooncoins. Bridge fittings cost 35 and lantern repairs cost 20. What remains?',['5 mooncoins','15 mooncoins','25 mooncoins'],0,'Subtract both costs from sixty.'),
 witness:quiz('Listen before deciding','One witness reports a rumor. Another brings a dated register. What should an investigator do?',['Treat the rumor as proof','Compare the source, dates and supporting evidence','Accuse the nearest person'],1,'Check what can actually be supported.'),
 fairprice:quiz('A fair workshop invoice','Boot materials cost 12 mooncoins and skilled work is priced at 18. What is the total?',['18 mooncoins','30 mooncoins','42 mooncoins'],1,'Add materials and labor.'),
 story:quiz('Aurelin’s lesson','In “The Elves and the Shoemaker,” how did the couple thank the helpers?',['They demanded more unpaid work','They made clothes and shoes for the elves','They locked the workshop'],1,'Gratitude gave the elves freedom to leave.'),
 seats:order('Set the story circle','Aurelin asks you to prepare the cushions, light the lantern, welcome listeners, then begin.',['Welcome listeners','Begin tale','Prepare cushions','Light lantern'],[2,3,0,1],'Make the room comfortable before inviting the listeners.'),
 fish:quiz('A patient riverside visit','The bank is slippery and a nesting bird is nearby. Choose a good fishing spot.',['The dry marked platform away from the nest','The wet edge beside the nest','A closed sanctuary pool'],0,'Respect wildlife and use the safe platform.'),
 dance:order('The festival dance','The dance caller says Left, Right, Turn, Bow. Follow the caller.',['Turn','Left','Bow','Right'],[1,3,0,2],'Take the two side steps before turning.'),
 pantry:quiz('Fern’s pantry puzzle','You need 3 cups of flour. The scoop holds half a cup. How many scoops?',['Three','Six','Nine'],1,'Two half-cup scoops fill one cup.'),
 kindnessgift:quiz('A thoughtful invitation','Your neighbor is tired after a long day. What should your invitation offer?',['A quiet cup of tea and the choice to say no','A compulsory all-night party','A list of chores'],0,'Let kindness leave room for someone else’s needs.')
};
const jobs=[
{id:'cobbler',name:'Silverstitch Cobbler',district:'workshop',room:'craft',person:'Master Cobble',resource:'thread',pay:32,titles:['Apprentice Stitcher','Trusted Cobbler','Master of the Bench'],sets:[['leather','stitch'],['repair','fairprice'],['leather','fairprice']]},
{id:'baker',name:'Moonleaf Baker',district:'capital',room:'tavern',person:'Fern',resource:'flour',pay:30,titles:['Kitchen Helper','Village Baker','Head Baker'],sets:[['bread','portions'],['pantry','bread'],['tea','portions']]},
{id:'healer',name:'Academy Apothecary',district:'academy',room:'potion',person:'Professor Thistle',resource:'herbs',pay:34,titles:['Herb Apprentice','Draught Keeper','Senior Apothecary'],sets:[['medicine','labels'],['herbs','medicine'],['labels','herbs']]},
{id:'gardener',name:'Greenhouse Keeper',district:'gardens',room:'garden',person:'Keeper Willow',resource:'flowers',pay:28,titles:['Seedling Tender','Garden Steward','Master Grower'],sets:[['soil','garden'],['bouquet','herbs'],['garden','bouquet']]},
{id:'librarian',name:'Family Archivist',district:'library',room:'portraits',person:'House historian',resource:'paper',pay:32,titles:['Shelf Assistant','Family Archivist','Keeper of Records'],sets:[['catalog','record'],['letter','catalog'],['record','witness']]},
{id:'courier',name:'Kingdom Courier',district:'market',room:'merchant',person:'Elian',resource:'timber',pay:36,titles:['Parcel Runner','Royal Courier','Route Captain'],sets:[['parcel','route'],['bridge','letter'],['route','parcel']]},
{id:'ranger',name:'Woodland Ranger',district:'forest',room:'well',person:'Willow',resource:'herbs',pay:30,titles:['Trail Helper','Woodland Ranger','Guardian of the Paths'],sets:[['bridge','kindness'],['fish','bouquet'],['kindness','bridge']]},
{id:'steward',name:'Royal Community Steward',district:'court',room:'court',person:'Queen Aveline',resource:'paper',pay:38,titles:['Council Aide','Community Steward','Royal Counselor'],sets:[['charter','budget'],['witness','charter'],['budget','record']]}
];
const step=(district,room,puzzle,text,requires)=>({district,room,puzzle,text,requires});
const quests=[
{id:'supper',name:'A Seat at Fern’s Table',giver:'Fern',reward:65,steps:[step('market','merchant','portions','Arrange enough supplies for Fern’s twelve guests.'),step('capital','tavern','bread','Prepare the woodland loaves.'),step('capital','tavern','tea','Set a welcoming tea service.')]},
{id:'parcel',name:'The Parcel with Two Addresses',giver:'Archivist Rowan',reward:70,steps:[step('capital','archive','letter','Read the original delivery label.'),step('library','portraits','catalog','Find the right family file.'),step('market','merchant','parcel','Return the corrected parcel to Elian.')]},
{id:'lanterns',name:'The Lanterns Along the River',giver:'Aurelia',reward:75,steps:[step('festival','lantern','melody','Learn the lantern-keeper’s refrain.'),step('workshop','craft','repair','Repair the loose lantern brackets.'),step('forest','well','bridge','Choose the safe route for the river procession.')]},
{id:'greenhouse',name:'The Garden That Stopped Blooming',giver:'Keeper Willow',reward:70,steps:[step('gardens','garden','soil','Investigate the greenhouse beds.'),step('academy','potion','herbs','Prepare the correct plant care supplies.'),step('gardens','garden','garden','Restore and mark a new moonflower bed.')]},
{id:'storycircle',name:'Aurelin’s Evening Story Circle',giver:'Aurelin',reward:80,steps:[step('forest','owlTreehouse','story','Read the Shoemaker tale, then discuss its lesson.','owlRead'),step('library','portraits','record','Prepare a fragile illustrated storybook.'),step('forest','owlTreehouse','seats','Welcome the listeners to the treehouse.')]},
{id:'charter',name:'The Roads Everyone Can Use',giver:'Queen Aveline',reward:90,steps:[step('court','court','budget','Check the public repair fund.'),step('capital','archive','witness','Compare the travelers’ testimony.'),step('court','court','charter','Propose an inclusive travel charter.')]},
{id:'courierboots',name:'Boots for the Long Way Home',giver:'Liora',reward:75,steps:[step('workshop','craft','leather','Choose the courier’s boot material.'),step('market','merchant','fairprice','Agree a fair workshop invoice.'),step('workshop','craft','stitch','Finish the quiet woodland boots.')]},
{id:'sanctuary',name:'A Quiet Corner for the Moonfox',giver:'Willow',reward:65,steps:[step('gardens','creatures','kindness','Work out what the frightened moonfox needs.'),step('forest','well','fish','Inspect the sanctuary’s riverside paths.'),step('gardens','creatures','bouquet','Plan a gentle habitat that keeps flowering.')]}
];
const leisure=[{id:'fishing',name:'Riverside Fishing',district:'forest',room:'well',puzzles:['fish','bridge'],reward:12,prize:'River stone'},{id:'music',name:'Lantern Melody',district:'festival',room:'lantern',puzzles:['melody','dance'],reward:15,prize:'Festival ribbon'},{id:'stars',name:'Stargazer’s Challenge',district:'academy',room:'runes',puzzles:['stars','stars'],reward:15,prize:'Star chart'},{id:'tea',name:'Cottage Tea Ritual',district:'home',room:'home',puzzles:['tea','kindnessgift'],reward:10,prize:'Pressed tea leaf'},{id:'pantry',name:'Fern’s Kitchen Challenge',district:'capital',room:'tavern',puzzles:['pantry','portions'],reward:15,prize:'Copper recipe card'}];
const people=[{id:'fern',name:'Fern',district:'capital',room:'tavern',gift:'flour',puzzle:'tea'},{id:'cobble',name:'Master Cobble',district:'workshop',room:'craft',gift:'thread',puzzle:'leather'},{id:'elian',name:'Elian',district:'market',room:'merchant',gift:'paper',puzzle:'parcel'},{id:'pip',name:'Pip',district:'home',room:'home',gift:'flowers',puzzle:'kindnessgift'},{id:'thistle',name:'Professor Thistle',district:'academy',room:'potion',gift:'herbs',puzzle:'medicine'},{id:'willow',name:'Keeper Willow',district:'gardens',room:'garden',gift:'flowers',puzzle:'bouquet'},{id:'aurelia',name:'Aurelia',district:'festival',room:'lantern',gift:'thread',puzzle:'melody'},{id:'aurelin',name:'Aurelin',district:'forest',room:'owlTreehouse',gift:'paper',puzzle:'story'}];
const upgrades=[{id:'teanook',name:'A cottage tea nook',coins:35,resource:'timber',amount:2,description:'A comfortable corner for visits and quiet evenings.'},{id:'workcorner',name:'Your personal sewing corner',coins:45,resource:'thread',amount:3,description:'A proper place for your craft and finished work.'},{id:'herbshelf',name:'A moonleaf drying shelf',coins:35,resource:'herbs',amount:3,description:'Keep the fragrance of the woodland in your home.'},{id:'reading',name:'The storybook reading nook',coins:50,resource:'paper',amount:3,description:'Make room for the stories you want to pass on.'},{id:'windowbox',name:'Flower-filled cottage windows',coins:30,resource:'flowers',amount:3,description:'A growing welcome at your own front door.'},{id:'supper',name:'A supper table for friends',coins:40,resource:'flour',amount:3,description:'Your home becomes a gathering place.'}];
const districts=['capital','market','home','gardens','festival','workshop','academy','forest','forgotten','court','library'];
const discoveryPuzzles={capital:'witness',market:'fairprice',home:'kindnessgift',gardens:'bouquet',festival:'melody',workshop:'stitch',academy:'stars',forest:'kindness',forgotten:'record',court:'charter',library:'catalog'};
const record=x=>x&&typeof x==='object'&&!Array.isArray(x);
function ensure(s){if(!record(s.cityLife))s.cityLife={};const l=s.cityLife;l.v=1;for(const k of ['jobs','worked','quests','friends','social','bag','daily','claimed','discoveries','upgrades','played'])if(!record(l[k]))l[k]={};for(const k of ['xp','questSteps','shifts','games'])if(!Number.isSafeInteger(l[k])||l[k]<0)l[k]=0;if(!Array.isArray(l.collection))l.collection=[];if(!Array.isArray(l.history))l.history=[];return l}
function day(s){return Number.isSafeInteger(s.day)&&s.day>0?s.day:1}
function stats(s){const l=ensure(s),k=String(day(s));if(!record(l.daily[k]))l.daily[k]={jobs:0,quests:0,games:0,talks:0,discoveries:0};return l.daily[k]}
function note(l,title){l.history.unshift(title);l.history=l.history.slice(0,40)}
function pay(s,coins,xp,title){const l=ensure(s);s.coins+=coins;l.xp+=xp;note(l,title+' · +'+coins+' mooncoins');return {ok:true,coins,xp,title}}
function puzzle(id){return P[id]}
function check(id,response){const p=P[id];if(!p)return false;return p.kind==='sequence'?Array.isArray(response)&&response.length===p.answer.length&&response.every((n,i)=>n===p.answer[i]):response===p.answer}
function place(station,where){return where&&station.district===where.district&&station.room===where.room&&!where.porch}
function jobStage(s,id){const j=jobs.find(j=>j.id===id);if(!j)return null;const l=ensure(s),key=day(s)+':'+id,n=l.jobs[id]||0,step=l.activeJob?.key===key?l.activeJob.step:0;return{job:j,key,step,puzzles:j.sets[(day(s)+n-1)%j.sets.length],done:!!l.worked[key],rank:Math.min(2,Math.floor(n/3)),completed:n}}
function startJob(s,id,where){const info=jobStage(s,id);if(!info||!place(info.job,where))return {ok:false,reason:'Go inside the job’s workplace first.'};if(info.done)return {ok:false,reason:'This shift is finished. A new shift opens next game day.'};const l=ensure(s);if(l.activeJob&&l.activeJob.key!==info.key&&l.activeJob.day===day(s))return {ok:false,reason:'Finish or leave your current shift before starting another.'};l.activeJob={id,key:info.key,day:day(s),step:info.step};return{ok:true}}
function answerJob(s,id,response,where){const i=jobStage(s,id),l=ensure(s);if(!i||!l.activeJob||l.activeJob.key!==i.key||i.done||!place(i.job,where))return{ok:false,reason:'This shift is not active at this workplace.'};const p=i.puzzles[i.step];if(!check(p,response))return{ok:false,reason:P[p]?.hint||'Try again.'};l.activeJob.step++;if(l.activeJob.step<i.puzzles.length)return{ok:true,next:true};l.worked[i.key]=true;l.jobs[id]=(l.jobs[id]||0)+1;l.shifts++;l.bag[i.job.resource]=(l.bag[i.job.resource]||0)+1;stats(s).jobs++;delete l.activeJob;advance(s,45);return pay(s,i.job.pay+i.rank*8,20,i.job.name+' shift complete')}
function advance(s,minutes){let total=s.minutes+minutes;s.day=day(s)+Math.floor(total/1440);s.minutes=total%1440}
function acceptQuest(s,id){if(!quests.some(q=>q.id===id))return{ok:false};const l=ensure(s);if(l.quests[id]?.complete)return{ok:false,reason:'This story is already complete.'};if(!l.quests[id])l.quests[id]={step:0,complete:false};return{ok:true}}
function questStage(s,id){const q=quests.find(q=>q.id===id),saved=ensure(s).quests[id];return q&&saved?{quest:q,progress:saved,step:q.steps[saved.step]}:null}
function answerQuest(s,id,response,where){const i=questStage(s,id);if(!i||i.progress.complete||!i.step||!place(i.step,where))return{ok:false,reason:'Visit the story’s current location first.'};if(i.step.requires==='owlRead'&&!(s.owlStories||[]).includes(0))return{ok:false,reason:'Read The Elves and the Shoemaker in Aurelin’s story room first.'};if(!check(i.step.puzzle,response))return{ok:false,reason:P[i.step.puzzle].hint};const l=ensure(s);i.progress.step++;l.questSteps++;stats(s).quests++;l.xp+=8;if(i.progress.step<i.quest.steps.length)return{ok:true,next:true};i.progress.complete=true;return pay(s,i.quest.reward,30,i.quest.name+' complete')}
function social(s,id,kind,where){const p=people.find(x=>x.id===id),l=ensure(s);if(!p||!place(p,where))return{ok:false,reason:'Meet this neighbor at their usual place first.'};const key=day(s)+':'+id+':'+kind;if(l.social[key])return{ok:false,reason:'You have shared this moment today. Come back tomorrow.'};if(kind==='gift'){if(!(l.bag[p.gift]>0))return{ok:false,reason:'You need one '+p.gift+' from a job shift.'};l.bag[p.gift]--;}else if(kind!=='talk')return{ok:false};l.social[key]=true;l.friends[id]=(l.friends[id]||0)+(kind==='gift'?3:1);stats(s).talks++;l.xp+=kind==='gift'?8:3;note(l,'A kind moment with '+p.name);if(l.friends[id]>=4){s.visitors??=[];if(['Pip','Fern','Liora'].includes(p.name)&&!s.visitors.includes(p.name))s.visitors.push(p.name);}return{ok:true,friend:l.friends[id]}}
function answerFavor(s,id,response,where){const p=people.find(x=>x.id===id),l=ensure(s),key=day(s)+':'+id+':favor';if(!p||!place(p,where)||l.social[key])return{ok:false,reason:'This favor is not available here today.'};if(!check(p.puzzle,response))return{ok:false,reason:P[p.puzzle].hint};l.social[key]=true;l.friends[id]=(l.friends[id]||0)+2;stats(s).talks++;return pay(s,8,8,'A favor for '+p.name)}
function leisureStage(s,id){const g=leisure.find(g=>g.id===id),l=ensure(s),key=day(s)+':'+id;return g?{game:g,key,done:!!l.played[key],step:l.activeGame?.key===key?l.activeGame.step:0}:null}
function startGame(s,id,where){const i=leisureStage(s,id),l=ensure(s);if(!i||!place(i.game,where)||i.done)return{ok:false,reason:'This game’s reward is available once per game day at its location.'};l.activeGame={id,key:i.key,step:i.step};return{ok:true}}
function answerGame(s,id,response,where){const i=leisureStage(s,id),l=ensure(s);if(!i||i.done||l.activeGame?.key!==i.key||!place(i.game,where))return{ok:false,reason:'Start the game at its location.'};const p=i.game.puzzles[i.step];if(!check(p,response))return{ok:false,reason:P[p].hint};l.activeGame.step++;if(l.activeGame.step<i.game.puzzles.length)return{ok:true,next:true};l.played[i.key]=true;l.games++;stats(s).games++;if(!l.collection.includes(i.game.prize))l.collection.push(i.game.prize);delete l.activeGame;advance(s,15);return pay(s,i.game.reward,12,i.game.name+' complete')}
function discover(s,id,response,where){const l=ensure(s);if(!districts.includes(id)||where?.district!==id||l.discoveries[id])return{ok:false,reason:'Explore a new district to find its keepsake.'};if(!check(discoveryPuzzles[id],response))return{ok:false,reason:P[discoveryPuzzles[id]].hint};l.discoveries[id]=true;stats(s).discoveries++;l.xp+=10;note(l,'Discovered '+id);return{ok:true}}
function buyUpgrade(s,id,where){const u=upgrades.find(u=>u.id===id),l=ensure(s);if(!u||where?.district!=='home'||where?.room!=='home'||l.upgrades[id])return{ok:false,reason:'Visit your cottage to add an unfinished home project.'};if(s.coins<u.coins||(l.bag[u.resource]||0)<u.amount)return{ok:false,reason:'You need '+u.coins+' mooncoins and '+u.amount+' '+u.resource+'.'};s.coins-=u.coins;l.bag[u.resource]-=u.amount;l.upgrades[id]=true;l.xp+=25;note(l,'Finished '+u.name);return{ok:true}}
function dailyCards(s){const shift=day(s)%3;return [{id:'work',title:'Earn an honest day’s pay',field:'jobs',goal:1,reward:18},{id:'adventure',title:shift===0?'Help two neighbors':shift===1&&Object.values(ensure(s).quests).filter(q=>q.complete).length<8?'Move a story forward':'Enjoy a little leisure',field:shift===0?'talks':shift===1&&Object.values(ensure(s).quests).filter(q=>q.complete).length<8?'quests':'games',goal:shift===0?2:1,reward:15},{id:'explore',title:Object.keys(ensure(s).discoveries).length<11?'Discover a neighborhood keepsake':'Share a moment with a neighbor',field:Object.keys(ensure(s).discoveries).length<11?'discoveries':'talks',goal:1,reward:12}].map(c=>({...c,key:day(s)+':'+c.id,current:stats(s)[c.field],claimed:!!ensure(s).claimed[day(s)+':'+c.id]}))}
function claimDaily(s,id){const c=dailyCards(s).find(c=>c.id===id),l=ensure(s);if(!c||c.claimed||c.current<c.goal)return{ok:false,reason:'Complete this objective before collecting its reward.'};l.claimed[c.key]=true;return pay(s,c.reward,10,'Daily objective: '+c.title)}
const milestones=[{id:'firstshift',title:'An Honest Day’s Work',goal:1,value:l=>l.shifts},{id:'regular',title:'A Trusted Working Neighbor',goal:8,value:l=>l.shifts},{id:'story',title:'A Story Brought Home',goal:1,value:l=>Object.values(l.quests).filter(q=>q.complete).length},{id:'allstories',title:'Threads of the Whole Kingdom',goal:8,value:l=>Object.values(l.quests).filter(q=>q.complete).length},{id:'explorer',title:'Every District, a Memory',goal:11,value:l=>Object.keys(l.discoveries).length},{id:'friend',title:'A Familiar Face',goal:4,value:l=>Math.max(0,...Object.values(l.friends))},{id:'home',title:'A Home Made by You',goal:3,value:l=>Object.keys(l.upgrades).length},{id:'games',title:'Make Time for Joy',goal:5,value:l=>l.games}];
function goals(s){const l=ensure(s);return milestones.map(m=>({id:m.id,title:m.title,goal:m.goal,value:m.value(l),complete:m.value(l)>=m.goal}))}
globalThis.EldoriaLifeModel={P,jobs,quests,people,leisure,upgrades,districts,discoveryPuzzles,ensure,day,stats,puzzle,check,place,jobStage,startJob,answerJob,acceptQuest,questStage,answerQuest,social,answerFavor,leisureStage,startGame,answerGame,discover,buyUpgrade,dailyCards,claimDaily,goals};
})();
